def estimate_wal_gb_per_hour(writes_per_sec: int, avg_entry_bytes: int = 800) -> float:
    if writes_per_sec <= 0 or avg_entry_bytes <= 0:
        raise ValueError('writes_per_sec and avg_entry_bytes must be positive')
    return round((writes_per_sec * avg_entry_bytes * 3600) / 1e9, 2)

def can_truncate_wal_segment(segment_max_index: int, durable_snapshot_index: int, suffix_keep: int = 10000) -> bool:
    if durable_snapshot_index < 0 or suffix_keep < 0:
        raise ValueError('Indices must be non-negative')
    safe_cutoff = max(0, durable_snapshot_index - suffix_keep)
    return segment_max_index <= safe_cutoff

def select_snapshot_strategy(engine_type: str) -> str:
    if engine_type == 'rocksdb_lsm':
        return 'ROCKSDB_HARDLINK_CHECKPOINT_ZERO_COPY'
    if engine_type == 'in_memory_map':
        return 'COW_FORK_OR_MVCC_CLONE'
    raise ValueError(f'Unsupported engine_type: {engine_type}')

def choose_replication_rpc(follower_next_idx: int, leader_first_log_idx: int) -> str:
    if follower_next_idx <= 0 or leader_first_log_idx <= 0:
        raise ValueError('Log indices must be >= 1')
    if follower_next_idx < leader_first_log_idx:
        return 'INSTALL_SNAPSHOT_RPC'
    return 'APPEND_ENTRIES_RPC'

def finalize_follower_snapshot(has_done_flag: bool, crc_valid: bool, snap_idx: int, local_last_idx: int) -> str:
    if not has_done_flag:
        return 'WAIT_MORE_CHUNKS'
    if not crc_valid:
        raise ValueError('Snapshot checksum mismatch; abort and retry')
    if snap_idx <= local_last_idx:
        return 'DISCARD_STALE_SNAPSHOT'
    return 'ATOMIC_SWAP_AND_RESET_LOG'

def snapshot_bandwidth_cap_mbps(nic_mbps: int, max_concurrent_streams: int, reserve_pct: float = 0.5) -> float:
    if nic_mbps <= 0 or max_concurrent_streams <= 0:
        raise ValueError('NIC bandwidth and stream count must be positive')
    usable = nic_mbps * (1.0 - reserve_pct)
    return round(usable / max_concurrent_streams, 2)

def should_compact_log(uncompacted_entries: int, wal_bytes: int, entry_thresh: int = 100_000, byte_thresh: int = 256 * 1024 * 1024) -> bool:
    if uncompacted_entries < 0 or wal_bytes < 0:
        raise ValueError('Counters must be non-negative')
    return uncompacted_entries >= entry_thresh or wal_bytes >= byte_thresh
